const allPayments = (collections['80cbde07-d7fc-4adb-bc47-1c9c92744c4f']?.data || []).filter(Boolean);

const summary = {
  paid: { total: 0, count: 0 },
  pending: { total: 0, count: 0 },
  overdue: { total: 0, count: 0 }
};

const today = new Date();

allPayments.forEach(p => {
  const dueDate = new Date(p.due_date);
  const amount = Number(p.amount) || 0;

  if (p.status === 'paid') {
    summary.paid.total += amount;
    summary.paid.count++;
  } else if (p.status === 'pending' && dueDate < today) {
    summary.overdue.total += amount;
    summary.overdue.count++;
  } else if (p.status === 'pending') {
    summary.pending.total += amount;
    summary.pending.count++;
  }
});

return [
  {
    id: "paid",
    label: { es: "Pagados", en: "Paid" },
    color: "#10B981",
    total: summary.paid.total,
    count: summary.paid.count
  },
  {
    id: "pending",
    label: { es: "Pendientes", en: "Pending" },
    color: "#44403C",
    total: summary.pending.total,
    count: summary.pending.count
  },
  {
    id: "overdue",
    label: { es: "Vencidos", en: "Overdue" },
    color: "#F43F5E",
    total: summary.overdue.total,
    count: summary.overdue.count
  }
];

